def count_sub_islands(grid1, grid2):
    rows, cols = len(grid2), len(grid2[0])

    def dfs(r, c):
        if r < 0 or r >= rows or c < 0 or c >= cols or grid2[r][c] == 0:
            return True
        grid2[r][c] = 0
        is_sub = grid1[r][c] == 1
        is_sub &= dfs(r + 1, c)
        is_sub &= dfs(r - 1, c)
        is_sub &= dfs(r, c + 1)
        is_sub &= dfs(r, c - 1)
        return is_sub

    count = 0
    for r in range(rows):
        for c in range(cols):
            if grid2[r][c] == 1 and dfs(r, c):
                count += 1
    return count

